import{z as s,x as o,o as r,c as p,q as i,j as A,D as t,d as a,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"电路分析的自动化","description":"","frontmatter":{"title":"电路分析的自动化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/xai-circuit-automation.md","filePath":"llm/xai-circuit-automation.md","lastUpdated":1791063341000}'),C={name:"llm/xai-circuit-automation.md"};function m(d,E,c,h,u,D){const B=o("Mermaid");return r(),p("div",null,[E[2]||(E[2]=i('<h1 id="电路分析的自动化" tabindex="-1">电路分析的自动化 <a class="header-anchor" href="#电路分析的自动化" aria-label="Permalink to &quot;电路分析的自动化&quot;">​</a></h1><div class="epigraph"><p>手工电路证明了模型里存在算法，也证明了人读不过来；自动化的任务不是替人下结论，是把候选假设的吞吐提上去。</p><footer>—— 据 Elhage et al., 2021 与 Conmy et al., 2023 的电路口径整理</footer></div><p><a href="/llm/xai-feature-validation">上一课</a>把单条特征钉到「可用」：释义、激活预测、带对照的干预。但行为由特征的<strong>通路</strong>产生，不是由单点产生；手工电路分析在 GPT-2 的 IOI 任务上证明了可行性，也证明了不可扩展——一人月读一条电路。<a href="/llm/circuit-tracing">Circuit Tracing 课</a>讲过替换模型流水线的全景；本课把「自动化」本身当主题：边怎么打分、图怎么搜、自动化到什么程度、以及用什么验收自动化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>电路是一个带权有向图：节点是位点上的组件或特征，边是激活间的线性效应。给定提示与目标行为，要输出一张候选图，且图上每条边原则上都能被干预检验。手工流程——读权重、挑头、<a href="/llm/activation-patching">path patching</a> 逐边验证——每步都靠人。自动化要回答三件事：边的分从哪来（消融效应还是梯度近似）；图从哪来（全图搜出来还是归因排出来）；以及自动化自己怎么验收。</p><p><span class="marginnote">这里的「电路」不是电学电路，是给模型内部画的一张有向图：节点是注意力头、神经元或 SAE 特征，边是「上游组件的输出改变了下游组件的激活」。所谓「找电路」，就是从亿万个连接里挑出完成某个具体行为（比如间接宾语识别）的最小子图——类似工程师在整机里定位出真正干活的那几个元件。</span></p><p>失败模式也是三种：归因近似在非线性强处失真，边权与真实介导不符；搜索空间组合爆炸，预算烧完图还没成型；图是相关结构，直接当因果讲——这正是上一课「相关簇」问题在通路层面的重演。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两条路线，实用中接成管线。</p><p><strong>归因式打分。</strong> 用梯度或局部线性近似一次给所有候选边打分：把边效应近似成上游激活、梯度与权重的乘积，按贡献排序剪枝。替换模型上的 <a href="/llm/attribution-graphs">attribution graphs</a> 把这套做成了流水线：稀疏特征当节点，线性化让贡献可加，一次反传覆盖全网。优点是吞吐，缺点是精度随非线性衰减。</p><p><strong>搜索式发现。</strong> ACDC（Conmy et al., 2023）从稠密图出发，逐条边做消融检验：删掉后行为差不变则删边，直到剩下的图仍复现行为。优点是每条边都被真消融过，缺点是组合爆炸——搜索空间必须先被压小。</p><p>压小靠字典：<strong>特征级电路</strong>（Marks et al., 2024）把节点从神经元换成上一课验证过的 <a href="/llm/sae-sparse-autoencoder">SAE</a> 特征，节点数降几个量级，归因粗筛加搜索细验才付得起。验收自动化本身有现成办法：在已知电路（IOI 一类）上对照真值算查准查全，再报 faithfulness——剪过的图仍复现行为——与 completeness——补边后不再冒出隐藏通路。</p>',12)),(r(),A(n,null,{default:t(()=>[l(B,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20BEH%5B%22%E7%9B%AE%E6%A0%87%E8%A1%8C%E4%B8%BA%EF%BC%9A%E6%8F%90%E7%A4%BA%E5%AF%B9%20%2B%20patching%20%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20SCORE%5B%22%E5%BD%92%E5%9B%A0%E5%BC%8F%E7%B2%97%E7%AD%9B%EF%BC%9A%E6%A2%AF%E5%BA%A6%E6%89%93%E8%BE%B9%E6%9D%83%22%5D%0A%20%20SCORE%20--%3E%20PRUNE%5B%22%E6%8C%89%E8%B4%A1%E7%8C%AE%E5%89%AA%E6%9E%9D%E6%88%90%E5%80%99%E9%80%89%E5%9B%BE%22%5D%0A%20%20PRUNE%20--%3E%20SEARCH%5B%22%E6%90%9C%E7%B4%A2%E5%BC%8F%E7%BB%86%E9%AA%8C%EF%BC%9A%E9%80%90%E8%BE%B9%E7%9C%9F%E6%B6%88%E8%9E%8D%22%5D%0A%20%20SEARCH%20--%3E%20GRAPH%5B%22%E5%80%99%E9%80%89%E7%94%B5%E8%B7%AF%22%5D%0A%20%20GRAPH%20--%3E%20PRED%5B%22%E5%B9%B2%E9%A2%84%E9%A2%84%E8%A8%80%EF%BC%9A%E5%A4%B9%E6%8C%81%E8%BE%B9%E7%9C%8B%E4%B8%8B%E6%B8%B8%22%5D%0A%20%20PRED%20--%3E%7C%E9%A2%84%E8%A8%80%E4%B8%8D%E7%AC%A6%7C%20SCORE%0A%20%20PRED%20--%3E%7C%E9%A2%84%E8%A8%80%E7%9B%B8%E7%AC%A6%7C%20REPORT%5B%22%E6%8A%A5%E6%9F%A5%E5%87%86%E6%9F%A5%E5%85%A8%20%2B%20faithfulness%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("两条路线的分野来自一个事实：归因是"),e("strong",null,"线性化"),a("。替换模型在当前激活附近近似分段线性，一阶贡献才可加；非线性越强、跨层越远，边权失真越大，且在重复消融下不稳定。搜索式对失真免疫——它只信真消融——但复杂度逼它依赖稀疏性先验。所以实用管线是「归因粗筛定搜索范围，消融细验定最终边」，两步都不能省。")],-1)),(r(),A(n,null,{default:t(()=>[l(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20ATT%5B%22%E5%BD%92%E5%9B%A0%E5%BC%8F%EF%BC%9A%E4%B8%80%E6%AC%A1%E5%8F%8D%E4%BC%A0%E5%85%A8%E5%9B%BE%E6%89%93%E5%88%86%22%5D%20--%3E%20CHEAP%5B%22%E5%90%9E%E5%90%90%E9%AB%98%EF%BC%8C%E4%BD%86%E9%9D%9E%E7%BA%BF%E6%80%A7%E5%BC%BA%E5%A4%84%E8%BE%B9%E6%9D%83%E5%A4%B1%E7%9C%9F%22%5D%0A%20%20ACDC%5B%22%E6%90%9C%E7%B4%A2%E5%BC%8F%EF%BC%9A%E9%80%90%E8%BE%B9%E7%9C%9F%E6%B6%88%E8%9E%8D%E6%A3%80%E9%AA%8C%22%5D%20--%3E%20SLOW%5B%22%E8%BE%B9%E6%9D%83%E5%8F%AF%E4%BF%A1%EF%BC%8C%E4%BD%86%E8%BE%B9%E6%95%B0%E7%BB%84%E5%90%88%E7%88%86%E7%82%B8%22%5D%0A%20%20CHEAP%20--%3E%20PIPE%5B%22%E7%AE%A1%E7%BA%BF%EF%BC%9A%E5%BD%92%E5%9B%A0%E7%B2%97%E7%AD%9B%E5%87%BA%E5%80%99%E9%80%89%E8%BE%B9%22%5D%0A%20%20SLOW%20--%3E%20PIPE%0A%20%20PIPE%20--%3E%20FINAL%5B%22%E6%B6%88%E8%9E%8D%E7%BB%86%E9%AA%8C%E5%AE%9A%E6%9C%80%E7%BB%88%E8%BE%B9%E9%9B%86%22%5D%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=i('<p><span class="marginnote">常见误区：归因打分高的边不一定真有用。梯度只是「轻轻推一下看会怎样」的线性近似，非线性强的通路可能分数很高，真消融时模型却绕路把功能补上了。所以粗筛给出的只能叫「候选」，每条进入最终图的边都该被真的掐断一次、确认行为真的变化——这正是两步管线不能省成一步的原因。</span></p><p>误差节点在这里第二次入账（第一次在训练监控）：归因与搜索都只在字典节点上走，字典没覆盖的计算全部漏进误差项。一张没有误差占比的电路图等于隐去了模型的未知部分——报告里误差占比高的图，结论要按比例打折。</p><p><span class="marginnote">性价比的量级感：归因式一次反传播给全部边打分，搜索式一条边要做一轮消融前向。没有粗筛直接全图 ACDC，边数过万时预算按月烧；粗筛把候选边砍掉两三个量级后，细验才从研究变成日常工序。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>图是<strong>提示局部</strong>的：换提示、换上下文长度，图就换；跨提示合并成「一条通用电路」是解释者的假设，不是方法的产出。自动化输出的是候选机制，验证责任仍在人——假设–干预闭环（<a href="/llm/circuit-tracing">电路追踪课</a>的口径）不能外包给打分器。特征级电路继承字典的绑定：换宽度、换 checkpoint，图作废重画。最后，图的语义命名——哪条路径「是」抑制、哪条「是」推理步骤——仍由人给出，自动化加速的是假设吞吐，不是结论。</p><p><span class="marginnote">为什么「图是提示局部的」要紧：如果把某张图写成「模型判断 X 的通用机制」放进报告或安全审计，换一个提示这条通路可能根本不存在，整段结论作废。负责任的写法是把图、触发它的提示与失败案例一起报告——这一步偷懒，后面基于它做的模型修改或风险评估就会落空。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>两条路线：归因式一次打分全线、搜索式逐边真消融；实用管线是粗筛加细验。</li><li>特征级电路把节点换成验证过的 SAE 特征，把搜索空间压小几个量级。</li><li>验收自动化用已知电路的查准查全，加上 faithfulness 与 completeness 双指标。</li><li>误差占比必须随图报告；图是提示局部、候选机制，结论由人担责。</li><li>出处：Elhage et al., <em>A Mathematical Framework for Transformer Circuits</em>, 2021；Conmy et al., 2023（ACDC）；Marks et al., 2024（Sparse Feature Circuits）。</li></ul>',8))])}const g=s(C,[["render",m]]);export{F as __pageData,g as default};
